import json,sys
snapshot=json.load(open(sys.argv[1]))
namespace,deployment=sys.argv[2:4]
for p in snapshot['pods']:
 if p['metadata']['namespace']==namespace and p['metadata'].get('labels',{}).get('io.kompose.service')==deployment:
  print(p['metadata']['name'],[s.get('state') for s in p.get('status',{}).get('containerStatuses',[])])
